using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration — API key from env, pinned model version
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Build the IChatClient through MEAI abstraction
// ---------------------------------------------------------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// ---------------------------------------------------------------------------
// Tools — web search + note-taking
// ---------------------------------------------------------------------------
var researchTools = new ResearchTools();

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// ---------------------------------------------------------------------------
// Create the agent with guardrails
// ---------------------------------------------------------------------------
var agentOptions = new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An agent that researches topics by searching the web and taking notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. tools],
    },
};

var agent = new ChatClientAgent(chatClient, agentOptions);

// ---------------------------------------------------------------------------
// Run the research loop
// ---------------------------------------------------------------------------
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    var session = new ChatClientAgentSession();

    var runOptions = new ChatClientAgentRunOptions(new ChatOptions())
    {
        // ChatClientAgentRunOptions inherits AgentRunOptions — additional per-call config
    };

    var prompt =
        $"""
        Research the following topic thoroughly: "{topic}"

        Follow these steps:
        1. Search the web for information about the topic (perform 2-3 searches with
           different queries to get broad coverage).
        2. As you find important facts, save them as notes using the note-taking tool.
        3. After gathering enough information, retrieve all your notes.
        4. Provide a well-structured summary of your findings, organized with headings
           and bullet points. Cite the sources you used.
        """;

    Console.WriteLine($"\nResearching: {topic}\n");

    try
    {
        await foreach (var update in agent.RunStreamingAsync(prompt, session, runOptions))
        {
            if (update.Text is { Length: > 0 } text)
                Console.Write(text);
        }

        Console.WriteLine("\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError during research: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");

// ===========================================================================
// Tool implementations
// ===========================================================================

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "application/json" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    /// <summary>Searches the web for information on the given query using DuckDuckGo.</summary>
    [Description("Searches the web for information. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query)
    {
        try
        {
            // Use the DuckDuckGo HTML endpoint (no API key needed)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            var html = await Http.GetStringAsync(url);

            // Parse simple result snippets from the HTML response
            var results = ParseDuckDuckGoResults(html);

            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"\n");
            for (var i = 0; i < Math.Min(results.Count, 5); i++)
            {
                var r = results[i];
                sb.AppendLine($"{i + 1}. **{r.Title}**");
                sb.AppendLine($"   URL: {r.Url}");
                sb.AppendLine($"   {r.Snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    /// <summary>Saves a research note for later reference.</summary>
    [Description("Saves a research note. Use this to record important facts, findings, or quotes discovered during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    /// <summary>Retrieves all saved research notes.</summary>
    [Description("Retrieves all previously saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"Saved notes ({_notes.Count}):\n");
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"  [{i + 1}] {_notes[i]}");

        return sb.ToString();
    }

    public void ClearNotes() => _notes.Clear();

    // ------------------------------------------------------------------
    // Minimal HTML parser for DuckDuckGo results
    // ------------------------------------------------------------------
    private static List<SearchResult> ParseDuckDuckGoResults(string html)
    {
        var results = new List<SearchResult>();

        // DuckDuckGo HTML results are in <a class="result__a"> for titles/URLs
        // and <a class="result__snippet"> for snippets
        var resultBlocks = html.Split("result__body", StringSplitOptions.RemoveEmptyEntries);

        foreach (var block in resultBlocks.Skip(1)) // skip the first split before any result
        {
            var title = ExtractBetween(block, "result__a", "</a>");
            var snippet = ExtractBetween(block, "result__snippet", "</a>");
            var href = ExtractHref(block, "result__a");

            if (string.IsNullOrWhiteSpace(title) && string.IsNullOrWhiteSpace(snippet))
                continue;

            results.Add(new SearchResult
            {
                Title = StripHtml(title),
                Snippet = StripHtml(snippet),
                Url = CleanDdgUrl(href),
            });
        }

        return results;
    }

    private static string ExtractBetween(string text, string startMarker, string endMarker)
    {
        var start = text.IndexOf(startMarker, StringComparison.Ordinal);
        if (start < 0) return string.Empty;

        // Move past the tag closure '>'
        var tagEnd = text.IndexOf('>', start + startMarker.Length);
        if (tagEnd < 0) return string.Empty;

        var contentStart = tagEnd + 1;
        var end = text.IndexOf(endMarker, contentStart, StringComparison.Ordinal);
        if (end < 0) return string.Empty;

        return text[contentStart..end];
    }

    private static string ExtractHref(string text, string marker)
    {
        var idx = text.IndexOf(marker, StringComparison.Ordinal);
        if (idx < 0) return string.Empty;

        var hrefIdx = text.LastIndexOf("href=\"", idx, StringComparison.Ordinal);
        if (hrefIdx < 0)
            hrefIdx = text.IndexOf("href=\"", idx, StringComparison.Ordinal);
        if (hrefIdx < 0) return string.Empty;

        var start = hrefIdx + 6;
        var end = text.IndexOf('"', start);
        if (end < 0) return string.Empty;

        return text[start..end];
    }

    private static string CleanDdgUrl(string url)
    {
        // DuckDuckGo wraps URLs through a redirect; extract the actual URL
        if (url.Contains("uddg=", StringComparison.Ordinal))
        {
            var paramStart = url.IndexOf("uddg=", StringComparison.Ordinal) + 5;
            var paramEnd = url.IndexOf('&', paramStart);
            var encoded = paramEnd > 0 ? url[paramStart..paramEnd] : url[paramStart..];
            return Uri.UnescapeDataString(encoded);
        }

        return url;
    }

    private static string StripHtml(string html)
    {
        if (string.IsNullOrEmpty(html)) return string.Empty;

        var sb = new StringBuilder(html.Length);
        var inTag = false;
        foreach (var c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) sb.Append(c);
        }

        return WebUtility.HtmlDecode(sb.ToString()).Trim();
    }
}

